/// Sets the first element of `sum` to `val`.  
/// If `sum` is empty, it pushes `val` as its first element.
fn set_first(sum: &mut Vec<i32>, val: i32) {
    if sum.is_empty() {
        sum.push(val);
    } else {
        sum[0] = val;
    }
}

